      ],
      "catchers": {
        "pattern": {
          "status": "absent",
          "where": "",
          "reach": "the shape a build would read, held here as its seed: a stacked name with no glossary entry, either a hyphenated compound or two nouns in a row used as a name. No such script exists under guardrails/, scripts/, or hooks/."
        },
